}

import { useState } from 'react';
import api, { USUARIOS } from './api.js';
import SelectorDeUsuario from './componentes/SelectorDeUsuario.jsx';
import Programacao from './paginas/programacao/Programacao.jsx';

export default function App() {
  const [usuarioId, setUsuarioId] = useState(() => api.obterUsuarioAtual() || USUARIOS[0].id);

  function trocarUsuario(id) {
    api.definirUsuario(id);
    setUsuarioId(id);
  }

  return (
    <main>
      <h1>Semana Acadêmica 2026</h1>
      <SelectorDeUsuario usuarios={USUARIOS} valor={usuarioId} aoTrocar={trocarUsuario} />
      <Programacao api={api} />
    </main>
  );
}

import { useEffect, useMemo, useState } from 'react';

export const DIAS = [
  { valor: '2026-10-19', rotulo: 'seg 19/10' },
  { valor: '2026-10-20', rotulo: 'ter 20/10' },
  { valor: '2026-10-21', rotulo: 'qua 21/10' },
  { valor: '2026-10-22', rotulo: 'qui 22/10' },
  { valor: '2026-10-23', rotulo: 'sex 23/10' },
];

export function diaEmBrasilia(iso) {
  return new Date(iso).toLocaleDateString('en-CA', { timeZone: 'America/Sao_Paulo' });
}

function horarioEmBrasilia(iso) {
  return new Date(iso)
    .toLocaleTimeString('pt-BR', {
      timeZone: 'America/Sao_Paulo',
      hour: '2-digit',
      minute: '2-digit',
      hour12: false,
    })
    .replace('24:', '00:');
}

function rotuloTipo(tipo) {
  return tipo === 'minicurso' ? 'Minicurso' : 'Palestra';
}

function encontroDoDia(atividade, dia) {
  return atividade.encontros.find((encontro) => diaEmBrasilia(encontro.inicio) === dia);
}

export default function Programacao({ api }) {
  const [dia, setDia] = useState(DIAS[0].valor);
  const [tipo, setTipo] = useState('');
  const [atividades, setAtividades] = useState(null);
  const [salas, setSalas] = useState([]);
  const [erro, setErro] = useState(null);

  const nomeDaSala = useMemo(() => {
    const mapa = {};
    for (const sala of salas) {
      mapa[sala.id] = sala.nome;
    }
    return (salaId) => mapa[salaId] || salaId;
  }, [salas]);

  useEffect(() => {
    api
      .listarSalas()
      .then(setSalas)
      .catch((erroDaApi) => setErro(erroDaApi));
  }, [api]);

  useEffect(() => {
    setErro(null);
    setAtividades(null);
    api
      .listarAtividades({ dia, tipo: tipo || undefined })
      .then(setAtividades)
      .catch((erroDaApi) => setErro(erroDaApi));
  }, [api, dia, tipo]);

  return (
    <section aria-label="Programação da Semana Acadêmica">
      <nav aria-label="Dia">
        {DIAS.map((d) => (
          <button
            key={d.valor}
            type="button"
            aria-pressed={d.valor === dia}
            onClick={() => setDia(d.valor)}
          >
            {d.rotulo}
          </button>
        ))}
      </nav>

      <div role="group" aria-label="Tipo de atividade">
        <button type="button" aria-pressed={tipo === ''} onClick={() => setTipo('')}>
          Todas
        </button>
        <button
          type="button"
          aria-pressed={tipo === 'palestra'}
          onClick={() => setTipo('palestra')}
        >
          Palestras
        </button>
        <button
          type="button"
          aria-pressed={tipo === 'minicurso'}
          onClick={() => setTipo('minicurso')}
        >
          Minicursos
        </button>
      </div>

      {erro && (
        <p role="alert">
          {erro.erro}: {erro.mensagem}
        </p>
      )}

      {!erro && atividades && atividades.length === 0 && (
        <p role="status">
          {tipo === 'palestra' && 'Nenhuma palestra para este dia.'}
          {tipo === 'minicurso' && 'Nenhum minicurso para este dia.'}
          {tipo === '' && 'Nenhuma atividade para este dia.'}
        </p>
      )}

      {atividades && atividades.length > 0 && (
        <ul>
          {atividades.map((atividade) => {
            const encontro = encontroDoDia(atividade, dia);
            return (
              <li key={atividade.id} aria-label={atividade.titulo}>
                <h3>{atividade.titulo}</h3>
                <p>
                  {rotuloTipo(atividade.tipo)}
                  {atividade.situacao === 'cancelada' && <strong> · Cancelada</strong>}
                </p>
                <p>{nomeDaSala(atividade.salaId)}</p>
                {encontro && (
                  <p>
                    {horarioEmBrasilia(encontro.inicio)}–{horarioEmBrasilia(encontro.fim)}
                  </p>
                )}
                <p>
                  {atividade.vagasRestantes} de {atividade.vagas} vagas
                </p>
              </li>
            );
          })}
        </ul>
      )}
    </section>
  );
}

import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import App from './App.jsx';

createRoot(document.getElementById('root')).render(
  <StrictMode>
    <App />
  </StrictMode>,
);

import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, expect, it, vi } from 'vitest';
import Programacao, { diaEmBrasilia } from './Programacao.jsx';

const SALAS = [
  { id: 'auditorio', nome: 'Auditório Central', capacidade: 200 },
  { id: 'sala-101', nome: 'Sala 101', capacidade: 40 },
  { id: 'lab-3', nome: 'Laboratório 3', capacidade: 20 },
];

const palestra = {
  id: 'atv_palestra01',
  titulo: 'Inteligência Artificial na educação',
  tipo: 'palestra',
  salaId: 'auditorio',
  vagas: 200,
  encontros: [
    { id: 'enc_palestra', inicio: '2026-10-19T19:00:00-03:00', fim: '2026-10-19T21:00:00-03:00' },
  ],
  cargaHorariaMinutos: 120,
  situacao: 'prevista',
  ocupadas: 0,
  vagasRestantes: 200,
  emEspera: 0,
};

const minicurso = {
  id: 'atv_minicurso02',
  titulo: 'Flutter do zero',
  tipo: 'minicurso',
  salaId: 'lab-3',
  vagas: 20,
  encontros: [
    { id: 'enc_minicurso1', inicio: '2026-10-19T19:00:00-03:00', fim: '2026-10-19T22:00:00-03:00' },
    { id: 'enc_minicurso2', inicio: '2026-10-20T19:00:00-03:00', fim: '2026-10-20T22:00:00-03:00' },
  ],
  cargaHorariaMinutos: 360,
  situacao: 'prevista',
  ocupadas: 0,
  vagasRestantes: 20,
  emEspera: 0,
};

function criarApiFalsa({ atividades = [], salas = SALAS } = {}) {
  return {
    listarSalas: vi.fn(async () => salas),
    listarAtividades: vi.fn(async ({ dia, tipo } = {}) =>
      atividades.filter(
        (atividade) =>
          (!dia || atividade.encontros.some((encontro) => diaEmBrasilia(encontro.inicio) === dia)) &&
          (!tipo || atividade.tipo === tipo),
      ),
    ),
  };
}

describe('Programacao', () => {
  it('mostra a lista vazia quando a API não tem atividade para o dia', async () => {
    const api = criarApiFalsa();
    render(<Programacao api={api} />);

    expect(await screen.findByText('Nenhuma atividade para este dia.')).toBeInTheDocument();
  });

  it('lista as atividades com sala e nome quando a API devolve atividades', async () => {
    const api = criarApiFalsa({ atividades: [palestra, minicurso] });
    render(<Programacao api={api} />);

    expect(await screen.findByText('Inteligência Artificial na educação')).toBeInTheDocument();
    expect(screen.getByText('Flutter do zero')).toBeInTheDocument();
    expect(screen.getByText('Auditório Central')).toBeInTheDocument();
    expect(screen.getByText('Laboratório 3')).toBeInTheDocument();
    expect(api.listarSalas).toHaveBeenCalledTimes(1);
    expect(api.listarAtividades).toHaveBeenCalledWith({ dia: '2026-10-19', tipo: undefined });
  });

  it('filtra por tipo mandando ?tipo e mostrando só as do tipo escolhido', async () => {
    const api = criarApiFalsa({ atividades: [palestra, minicurso] });
    render(<Programacao api={api} />);
    await screen.findByText('Inteligência Artificial na educação');

    await userEvent.click(screen.getByRole('button', { name: 'Minicursos' }));

    expect(screen.getByText('Flutter do zero')).toBeInTheDocument();
    expect(screen.queryByText('Inteligência Artificial na educação')).not.toBeInTheDocument();
    expect(api.listarAtividades).toHaveBeenLastCalledWith({
      dia: '2026-10-19',
      tipo: 'minicurso',
    });
  });

  it('mostra a atividade cancelada com o aviso de cancelada', async () => {
    const cancelada = {
      ...palestra,
      id: 'atv_cancelada03',
      titulo: 'Palestra que não vai acontecer',
      situacao: 'cancelada',
    };
    const api = criarApiFalsa({ atividades: [cancelada] });
    render(<Programacao api={api} />);

    expect(await screen.findByText('Palestra que não vai acontecer')).toBeInTheDocument();
    expect(screen.getByText('Cancelada')).toBeInTheDocument();
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import api, { API_URL, USUARIOS } from './api.js';

describe('api.js', () => {
  beforeEach(() => {
    localStorage.clear();
    globalThis.fetch = vi.fn(async () => ({ ok: true, json: async () => [] }));
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  it('tem os 10 usuários da seção 4 do contrato', () => {
    expect(USUARIOS).toHaveLength(10);
    expect(USUARIOS.map((usuario) => usuario.id)).toEqual([
      'org-ana',
      'org-bruno',
      'p-carla',
      'p-diego',
      'p-elisa',
      'p-fabio',
      'p-gabriela',
      'p-heitor',
      'p-isadora',
      'p-joao',
    ]);
  });

  it('le API_URL do ambiente com fallback para localhost', () => {
    expect(API_URL).toMatch(/^https?:\/\/.+/);
  });

  it('manda X-Usuario em toda chamada quando há usuário no localStorage', async () => {
    api.definirUsuario('p-carla');
    await api.listarSalas();

    expect(globalThis.fetch).toHaveBeenCalledWith(
      `${API_URL}/salas`,
      expect.objectContaining({ headers: { 'X-Usuario': 'p-carla' } }),
    );
  });

  it('lista atividades com os filtros dia e tipo na query string', async () => {
    api.definirUsuario('org-ana');
    await api.listarAtividades({ dia: '2026-10-20', tipo: 'minicurso' });

    expect(globalThis.fetch).toHaveBeenCalledWith(
      `${API_URL}/atividades?dia=2026-10-20&tipo=minicurso`,
      expect.objectContaining({ headers: { 'X-Usuario': 'org-ana' } }),
    );
  });

  it('rejeita com o erro da API quando a resposta não é ok', async () => {
    globalThis.fetch = vi.fn(async () => ({
      ok: false,
      status: 422,
      json: async () => ({ erro: 'DADOS_INVALIDOS', mensagem: '?tipo só aceita palestra ou minicurso.' }),
    }));

    await expect(api.listarAtividades({ tipo: 'oficina' })).rejects.toMatchObject({
      erro: 'DADOS_INVALIDOS',
      status: 422,
    });
  });
});

